public class MaxValue {

    public static class MaxMapper extends Mapper<Object, Text, Text, DoubleWritable> {
        private Text deptId = new Text();
        private DoubleWritable salary = new DoubleWritable();

        public void map(Object key, Text value, Context context) throws IOException, InterruptedException {
            String line = value.toString().trim();
            if (line.startsWith("emp_id") || line.isEmpty()) return; // skip header
            String[] parts = line.split(",");
            if (parts.length >= 4) {
                deptId.set(parts[2].trim());
                salary.set(Double.parseDouble(parts[3].trim()));
                context.write(deptId, salary);
            }
        }
    }

    public static class MaxReducer extends Reducer<Text, DoubleWritable, Text, DoubleWritable> {
        private DoubleWritable result = new DoubleWritable();

        public void reduce(Text key, Iterable<DoubleWritable> values, Context context) throws IOException, InterruptedException {
            double max = Double.MIN_VALUE;
            for (DoubleWritable val : values) {
                if (val.get() > max) {
                    max = val.get();
                }
            }
            result.set(max);
            context.write(key, result);
        }
    }

    public static void main(String[] args) throws Exception {
        Configuration conf = new Configuration();
        Job job = Job.getInstance(conf, "max value");
        job.setJarByClass(MaxValue.class);
        job.setMapperClass(MaxMapper.class);
        job.setReducerClass(MaxReducer.class);
        job.setOutputKeyClass(Text.class);
        job.setOutputValueClass(DoubleWritable.class);
        FileInputFormat.addInputPath(job, new Path("employees.csv"));
        FileOutputFormat.setOutputPath(job, new Path("output_max_salary"));
        System.exit(job.waitForCompletion(true) ? 0 : 1);
    }
}

