public class AverageCalculation {
    public static class AvgMapper extends Mapper<Object, Text, Text, DoubleWritable> {
        private Text major = new Text();
        private DoubleWritable gpa = new DoubleWritable();

        public void map(Object key, Text value, Context context) throws IOException, InterruptedException {
            String line = value.toString().trim();
            if (line.startsWith("id") || line.isEmpty()) return;
            String[] parts = line.split(",");
            if (parts.length >= 6) {
                major.set(parts[4].trim());
                gpa.set(Double.parseDouble(parts[5].trim()));
                context.write(major, gpa);
            }
        }
    }

    public static class AvgReducer extends Reducer<Text, DoubleWritable, Text, DoubleWritable> {
        private DoubleWritable result = new DoubleWritable();
        public void reduce(Text key, Iterable<DoubleWritable> values, Context context) throws IOException, InterruptedException {
            double sum = 0.0;
            int count = 0;
            for (DoubleWritable val : values) {
                sum += val.get();
                count++;
            }
            double avg = count > 0 ? sum / count : 0.0;
            result.set(Math.round(avg * 100.0) / 100.0);
            context.write(key, result);
        }
    }

    public static void main(String[] args) throws Exception {
        Configuration conf = new Configuration();
        Job job = Job.getInstance(conf, "average calculation");
        job.setJarByClass(AverageCalculation.class);
        job.setMapperClass(AvgMapper.class);
        job.setReducerClass(AvgReducer.class);
