public class InvertedIndex {
    public static class IndexMapper extends Mapper<Object, Text, Text, Text> {
        private Text word = new Text();
        private Text location = new Text();

        public void map(Object key, Text value, Context context) throws IOException, InterruptedException {
            String line = value.toString();
            location.set(key.toString());
            StringTokenizer itr = new StringTokenizer(line);
            while (itr.hasMoreTokens()) {
                String w = itr.nextToken().replaceAll("[^a-zA-Z]", "").toLowerCase();
                if (!w.isEmpty()) {
                    word.set(w);
                    context.write(word, location);
                }
            }
        }
    }

    public static class IndexReducer extends Reducer<Text, Text, Text, Text> {
        public void reduce(Text key, Iterable<Text> values, Context context) throws IOException, InterruptedException {
            StringBuilder sb = new StringBuilder();
            for (Text val : values) {
                if (sb.length() > 0) sb.append(", ");
                sb.append(val.toString());
            }
            context.write(key, new Text("[" + sb.toString() + "]"));
        }
    }

    public static void main(String[] args) throws Exception {
        Configuration conf = new Configuration();
        Job job = Job.getInstance(conf, "inverted index");
        job.setJarByClass(InvertedIndex.class);
        job.setMapperClass(IndexMapper.class);
        job.setReducerClass(IndexReducer.class);
        job.setOutputKeyClass(Text.class);
        job.setOutputValueClass(Text.class);
        FileInputFormat.addInputPath(job, new Path("wordcount_input.txt"));
        FileOutputFormat.setOutputPath(job, new Path("output_inverted_index"));
        System.exit(job.waitForCompletion(true) ? 0 : 1);
    }
}

