import java.util.*;
import java.util.stream.Collectors;

public class GradeAnalyzer {
    static class Student {
        String name;
        String major;
        double gpa;

        Student(String name, String major, double gpa) {
            this.name = name;
            this.major = major;
            this.gpa = gpa;
        }
    }

    public static void main(String[] args) {
        System.out.println("=== Big Data Online Lab: Java OOP Analyzer ===");
        List<Student> list = List.of(
            new Student("Alice", "Computer Science", 3.85),
            new Student("Bob", "Data Science", 3.42),
            new Student("Charlie", "Computer Science", 3.91),
            new Student("Diana", "Data Science", 3.75),
            new Student("Evan", "Software Engineering", 3.60)
        );

        double avgGpa = list.stream().mapToDouble(s -> s.gpa).average().orElse(0.0);
        System.out.printf("Total Students: %d | Average GPA: %.2f%n%n", list.size(), avgGpa);

        System.out.println("Students Grouped by Major:");
        list.stream()
            .collect(Collectors.groupingBy(s -> s.major))
            .forEach((major, students) -> {
                System.out.printf("  * %s: %d students%n", major, students.size());
            });
    }
}

